// A chain-game contract that maintains a 'throne' which agents may pay to rule.
// See www.kingoftheether.com & https://github.com/kieranelby/ThroneGame .
// (c) Kieran Elby 2016. All rights reserved.
// v0.4.0.
// Inspired by ethereumpyramid.com and the (now-gone?) "magnificent bitcoin gem".

// This contract lives on the blockchain at 0xb336a86e2feb1e87a328fcb7dd4d04de3df254d0
// and was compiled (using optimization) with:
// Solidity version: 0.2.1-fad2d4df/.-Emscripten/clang/int linked to libethereum

// For future versions it would be nice to ...
// TODO - enforce time-limit on reign (can contracts do that without external action)?
// TODO - add a random reset?
// TODO - add bitcoin bridge so agents can pay in bitcoin?
// TODO - maybe allow different return payment address?
pragma solidity ^0.4.19;

contract ThroneGame {

    struct Ruler {
        // Address to which their payout will be sent.
        address payoutAddress;
        // A rulerName by which they wish to be known.
        // NB: Unfortunately "string" seems to expose some bugs in web3.
        string rulerName;
        // How much did they pay to become monarch?
        uint paidAmount;
        // When did their rule start (based on block.timestamp)?
        uint reignStart;
    }

    // The wizard is the hidden power behind the throne; they
    // occupy the throne during gaps in succession and collect fees.
    address gameMaster;

    // Used to ensure only the wizard can do some things.
    modifier onlyMaster { if (msg.sender == gameMaster) _; }

    // How much must the first monarch pay?
    uint constant basePrice = 100 finney;

    // The next paidAmount is calculated from the previous claimFee
    // by multiplying by claimFeeAdjustNum and dividing by claimFeeAdjustDen -
    // for example, num=3 and den=2 would cause a 50% increase.
    uint constant priceGrowthNum = 3;
    uint constant priceGrowthDen = 2;

    // How much of each claimFee goes to the wizard (expressed as a fraction)?
    // e.g. num=1 and den=100 would deduct 1% for the wizard, leaving 99% as
    // the payout fee for the usurped monarch.
    uint constant commissionNum = 1;
    uint constant commissionDen = 100;

    // How much must an agent pay now to become the monarch?
    uint public currentPrice;

    // The King (or Queen) of the Ether.
    Ruler public currentRuler;

    // Earliest-first list of previous throne holders.
    Ruler[] public pastRulers;

    // Create a new throne, with the creator as wizard and first ruler.
    // Sets up some hopefully sensible defaults.
    function ThroneGame() {
        gameMaster = msg.sender;
        currentPrice = basePrice;
        currentRuler = Ruler(
            gameMaster,
            "[Vacant]",
            0,
            block.timestamp
        );
    }

    function getRulerCount() constant returns (uint n) {
        return pastRulers.length;
    }

    // Fired when the throne is claimed.
    // In theory can be used to help build a front-end.
    event RulerSeized(
        address newRulerAddress,
        string newRulerName,
        uint newPrice
    );

    // Fallback function - simple transactions trigger this.
    // Assume the message data is their desired rulerName.
    function() {
        seizeThrone(string(msg.data));
    }

    // Claim the throne for the given rulerName by paying the currentClaimFee.
    function seizeThrone(string rulerName) {

        uint paid = msg.value;

        // If they paid too little, reject claim and refund their money.
        if (paid < currentPrice) {
            msg.sender.send(paid);
            return;
        }

        // If they paid too much, continue with claim but refund the excess.
        if (paid > currentPrice) {
            uint refund = paid - currentPrice;
            msg.sender.send(refund);
            paid = paid - refund;
        }

        // The claim price payment goes to the current monarch as payout
        // (with a commission held back for the wizard). We let the wizard's
        // payments accumulate to avoid wasting gas sending small fees.

        uint commission = (paid * commissionNum) / commissionDen;

        uint payout = paid - commission;

        if (currentRuler.payoutAddress != gameMaster) {
            currentRuler.payoutAddress.send(payout);
        } else {
            // When the throne is vacant, the fee accumulates for the wizard.
        }

        // Usurp the current monarch, replacing them with the new one.
        pastRulers.push(currentRuler);
        currentRuler = Ruler(
            msg.sender,
            rulerName,
            paid,
            block.timestamp
        );

        // Increase the claim fee for next time.
        // Stop number of trailing decimals getting silly - we round it a bit.
        uint nextPrice = currentPrice * priceGrowthNum / priceGrowthDen;
        if (nextPrice < 10 finney) {
            currentPrice = nextPrice;
        } else if (nextPrice < 100 finney) {
            currentPrice = 100 szabo * (nextPrice / 100 szabo);
        } else if (nextPrice < 1 ether) {
            currentPrice = 1 finney * (nextPrice / 1 finney);
        } else if (nextPrice < 10 ether) {
            currentPrice = 10 finney * (nextPrice / 10 finney);
        } else if (nextPrice < 100 ether) {
            currentPrice = 100 finney * (nextPrice / 100 finney);
        } else if (nextPrice < 1000 ether) {
            currentPrice = 1 ether * (nextPrice / 1 ether);
        } else if (nextPrice < 10000 ether) {
            currentPrice = 10 ether * (nextPrice / 10 ether);
        } else {
            currentPrice = nextPrice;
        }

        // Hail the new monarch!
        RulerSeized(currentRuler.payoutAddress, currentRuler.rulerName, currentPrice);
    }

    // Used only by the wizard to collect his commission.
    function collectCommission(uint amount) onlyMaster {
        gameMaster.send(amount);
    }

    // Used only by the wizard to collect his commission.
    function handoverGame(address newOwner) onlyMaster {
        gameMaster = newOwner;
    }

}
